  ('curation-pathway-diagram-page', 'Curation tools', 'Pathway diagram page', '/rgdweb/pathway/pathwayRecord.html?acc_id=PW:0000024', 'Pathway page and diagram load like production.', 'pathway/chart.html', 'N', 'N', 1240),
  ('curation-entity-tagger-pdf-upload-and-recognition', 'Curation tools', 'Entity tagger (PDF upload and recognition)', '/rgdweb/curation/entityTagger/main.html', 'Upload a test PDF, run entity recognition, view the recognized entities and annotations. Known before testing: its tables (BATCH_PROCESSING_JOBS, CURATION_SESSIONS, RECOGNIZED_ENTITIES) exist in neither Oracle nor PostgreSQL, so anything that saves a session or job is expected to fail on both. Record what works and what fails.', 'curation/entityTagger/index.html, curation/pdf/upload|status|cancel|session-info.html, curation/entity/recognize.html, curation/annotation/view.html, curation/recover-session.html, curation/terminate-session.html', 'Y', 'Y', 1250),
  ('curation-obsolete-go-terms', 'Curation tools', 'Obsolete GO terms', '/rgdweb/curation/edit/obsoleteGoTerms.html', 'List of obsolete GO terms with annotations loads and matches the Oracle curation build.', NULL, 'Y', 'Y', 1260),
  ('curation-expression-metadata-download', 'Curation tools', 'Expression metadata download', '/rgdweb/curation/expression/downloadMetaData.html', 'Download metadata for an experiment; file opens and rows match the Oracle curation build.', NULL, 'Y', 'Y', 1270),
  ('php-sign-in-menu-and-logout', 'PHP curation tool', 'Sign in, menu and logout', '/rgdCuration/?module=mainPage&func=contents', 'Sign in with GitHub (you must be a rat-genome-database member). The menu shows every tool, the user name appears, and Logout works. No PHP warnings on the page. Sign-in stays on newdev.', 'admin_logout, mainPage_*', 'Y', 'Y', 1280),
  ('php-select-objects-bucket', 'PHP curation tool', 'Select objects (bucket)', '/rgdCuration/?module=curation&func=selectObjects', 'Search genes, QTLs, strains and SSLPs by symbol and by RGD ID; add each to the bucket; clear buckets. Searching a QTL or SSLP by RGD ID must return within a few seconds (it hung on PostgreSQL before a fix). A numeric strain search now lists active strains only.', 'searchObjects, addGeneToBucket, addQTLToBucket, addStrainToBucket, addSSLPToBucket, clearSessionObjects, clearAllCurationBuckets', 'Y', 'Y', 1290),
  ('php-select-terms', 'PHP curation tool', 'Select terms', '/rgdCuration/?module=curation&func=selectTerms', 'Search terms in GO, RDO, MP, PW and other ontologies (contains and exact match); add terms to the bucket; clear terms. Results match the Oracle tool.', 'addTermToBucket, clearSessionTerms', 'Y', 'Y', 1300),
  ('php-select-references', 'PHP curation tool', 'Select references', '/rgdCuration/?module=curation&func=selectReferences', 'Search references by keyword, author and year; add references; add by PubMed ID; check the not-found list.', 'addReferences, addReferenceToBucket, addPubmedIDToBucket, referencesNotFound, clearSessionReferences', 'Y', 'Y', 1310),
  ('php-create-and-edit-annotations', 'PHP curation tool', 'Create and edit annotations', '/rgdCuration/?module=curation&func=EditAnnotation', 'With objects, terms and a reference in the buckets, create a TEST annotation with and without qualifier/notes; edit it; then delete it (My annotations). Empty qualifier/notes must be stored empty (NULL), duplicates must be refused. Existing annotations for the selected genes display with their notes.', 'linkAnnotation, createAnnotationRelationship', 'Y', 'Y', 1320),
  ('php-associations', 'PHP curation tool', 'Associations', '/rgdCuration/?module=curation&func=makeAss', 'Link a TEST object to a reference, gene to gene, QTL to QTL and core object to core object; each link saves and shows on the report page; remove the test links afterwards.', 'linkCoreToRef, linkCoreToCore, linkQTLtoQTL, createCoretoRefRelationship, createCoretoCoreRelationship, createQTLtoQTLRelationship', 'Y', 'Y', 1330),
  ('php-gene-description-update', 'PHP curation tool', 'Gene description update', '/rgdCuration/?module=curation&func=updateGeneDescriptionPopup', 'Update a TEST gene''s description, and clear it; the report page shows the change. An empty description must be stored empty (NULL).', NULL, 'Y', 'Y', 1340),
  ('php-object-edit-qtl-editor', 'PHP curation tool', 'Object edit (QTL editor)', '/rgdCuration/?module=objectEdit&func=selectObjects', 'Open an existing QTL (page loads; it failed to parse on PHP 8 before a fix), edit fields, and save a TEST QTL with LOD, p-value, peak offset and variance left empty (this failed on PostgreSQL before a fix).', 'objectEdit_updateQTLS', 'Y', 'Y', 1350),
  ('php-merge-retire-and-split-objects', 'PHP curation tool', 'Merge, retire and split objects', '/rgdCuration/?module=objectNomen&func=selectObjects', 'Search genes by name and RGD ID (results now capped at the first 500 by RGD ID); run a merge/retire on TEST records only.', NULL, 'Y', 'Y', 1360),
  ('php-notes-editor', 'PHP curation tool', 'Notes editor', '/rgdCuration/?module=notesEdit&func=selectObjects', 'Find an object, add and edit a TEST note.', NULL, 'Y', 'Y', 1370),
  ('php-reference-editor', 'PHP curation tool', 'Reference editor', '/rgdCuration/?module=reference&func=Contents', 'Open and edit a TEST reference.', NULL, 'Y', 'Y', 1380),
  ('php-obsolete-terms-and-annotation-buckets', 'PHP curation tool', 'Obsolete terms and annotation buckets', '/rgdCuration/?module=ont&func=obsoleteTerms', 'Obsolete-term list loads (it took 18 s on PostgreSQL; Oracle timed out); create a bucket, add and remove annotations, update an annotation''s term on TEST data, delete the bucket.', 'ont_newBucket, addAnnotToBucket, addAnnotsToBucket, removeAnnotFromBucket, updateAnnotTerm, deleteAnnotInBucket, emptyBucket, deleteBucket, bucket, annotations', 'Y', 'Y', 1390),
  ('php-my-annotations', 'PHP curation tool', 'My annotations', '/rgdCuration/?module=curationMaint&func=showMyAnnotation', 'List your annotations for a date range and delete a TEST annotation. Known: slow on PostgreSQL (about 40 s vs 4 s on Oracle); record the time.', 'curationMaint_deleteAnnotation', 'Y', 'Y', 1400),
  ('php-lookup-tables', 'PHP curation tool', 'Lookup tables', '/rgdCuration/?module=tableMaint&func=home', 'View, add, edit and delete a TEST row in process types, gene types, RGD XDB and XDB species. Duplicate checks still refuse existing names.', 'processTypes, geneTypes, RGDxdb, RGDxdbSpecies and their update/delete functions', 'Y', 'Y', 1410),
  ('php-reports-home-and-basic-reports', 'PHP curation tool', 'Reports home and basic reports', '/rgdCuration/?module=report&func=home', 'Open each report: basic, all annotations, GO, DO, PW, MP, references, nomenclature, gene history, created genes (by month, mine). Counts match the Oracle tool (allow for records added after 2026-09-14). CSV export works.', 'report_* (basicReportHome, allAnnotReportHome, GOHome, DOHome, PWHome, MPHome, RefHome, nomenHome, geneHistory, geneCreatedReport, dataToCSV2, ...), report2_procTypeDescChosen', 'Y', 'Y', 1420),
  ('php-statistics-reports-report3', 'PHP curation tool', 'Statistics reports (report3)', '/rgdCuration/?module=report3&func=GenesStart', 'Run one report from each family, monthly and cumulative, with and without the pipeline option: genes, variants, pseudogenes, references, GO, MBCA, evidence/not-evidence, alleles, KP, any annotations, percent annotated, XDB. Counts match the Oracle tool. Known: XDB reports for very large databases time out on both; percent annotated and the plain XDB report already fail on Oracle.', 'report3_*Start (45 entry points)', 'Y', 'Y', 1430),
  ('php-annotation-report-with-graphs-report5', 'PHP curation tool', 'Annotation report with graphs (report5)', '/rgdCuration/?module=report5&func=MainSearch', 'Choose species, object type, user, ontology and dates; run objects-annotated and annotations, monthly and cumulative; graphs draw and CSV export works. The user list shows first and last names.', 'reportGraph_graphPrep, CSVPrep, CumgraphPrep, CumCSVPrep', 'Y', 'Y', 1440),
  ('php-search-engine-and-site-map-pages', 'PHP curation tool', 'Search engine and site map pages', '/rgdCuration/?module=searchEngine&func=showAll', 'Rat, human and mouse gene/QTL lists, gene and QTL details, rat strains, and the site-map generators load with data.', 'searchEngine_*, siteMap_*, strains module', 'Y', 'Y', 1450),
  ('php-portal-admin', 'PHP curation tool', 'Portal admin', '/rgdCuration/?module=portalAdmin&func=processPortal', 'Known before testing: the portal tables do not exist in Oracle or PostgreSQL, so these pages fail on both. Pass if newdev behaves the same as the Oracle tool (no new errors).', 'portalAdmin_*, portal_* and the portal page blocks', 'Y', 'Y', 1460),
  ('related-rest-api-rgdws', 'Related applications', 'REST API (rgdws)', '/rgdws/swagger-ui/index.html', 'Try one call in each section; results match rest.rgd.mcw.edu. Includes the expression endpoints used by gene pages.', 'rgd-web-services', 'N', 'N', 1470),
  ('related-alliance-gene-pages', 'Related applications', 'Alliance gene pages', '/rgdweb/agr/ratGene/index.jsp', 'Pages load.', 'agr/*', 'N', 'Y', 1480)
