-- The pages and tools to test (148 items: the web application in its production and curation builds,
-- and the PHP curation tool rgdCuration). Generated from the test plan; re-running replaces the item
-- definitions and keeps assignments, results and sign-offs.

ON CONFLICT (item_id) DO UPDATE SET area=EXCLUDED.area, name=EXCLUDED.name, path=EXCLUDED.path,
  check_text=EXCLUDED.check_text, covers=EXCLUDED.covers, curation=EXCLUDED.curation,
  no_compare=EXCLUDED.no_compare, sort_order=EXCLUDED.sort_order;
